'use strict';
/**
 * SOKONI — TENANT IDENTITY RESOLVER
 *
 * The POS has two tenant spaces, proven by construction in
 * docs/TENANT_IDENTITY_CENSUS.md:
 *
 *   OWNER-UID SPACE            shops/{uid}, sellers/{uid}, shopEmployees.shopOwnerId
 *   GENERATED-MERCHANT SPACE   businesses/{merchantId}, workspaceMemberships.businessId,
 *                              posStaff.merchantId, branchId
 *
 * `merchantId` is generated by `_generateMerchantId()`, so it can never equal an auth uid.
 * Nothing in the codebase linked the two spaces, which let `sellerId` mean a uid when an
 * owner called and a merchantId when staff called — the same shop addressed two ways, and
 * the reason a staff-raised approval was invisible to an owner-manager.
 *
 * THIS MODULE IS THE MISSING LINK, AND NOTHING MORE.
 *   · it creates no collection and no second identifier
 *   · it never reads `businesses.businessId` — that field is a decorative 'BIZ-…' label,
 *     not a key (census §1)
 *   · it never infers a merchant from a name, a prefix or a document-id shape
 *   · it never accepts a caller-supplied merchantId as proof of anything
 *
 * IT FAILS CLOSED, and here is the accurate reason — an earlier version of this comment
 * overstated it. There are 13 `where('ownerId','==',uid)` lookups; SEVEN use `.limit(1)`.
 * None of them is a cross-tenant hole: every one that goes on to use the id either re-checks
 * `ownerId !== uid` afterwards, or uses only `size > 0`. What they can do is silently pick
 * the WRONG BUSINESS AMONG THE CALLER'S OWN — which for a payment destination means money
 * routed to the wrong till of the same owner.
 *
 * Two of the seven are correct as they stand and must not be converged:
 * `_ensureBusinessForOwner` asks only whether any business exists (a provisioning guard), and
 * `profileGetCompletion` uses only `size > 0`. Making those refuse on ambiguity would break
 * multi-business owners for no gain.
 */

const admin = require('firebase-admin');
if (!admin.apps.length) admin.initializeApp();
const db = () => admin.firestore();

/** Reasons a resolution can fail. Each is distinct so callers can report honestly. */
const REASON = {
  UNLINKED:  'no-business-for-owner',
  AMBIGUOUS: 'owner-has-multiple-businesses',
  MALFORMED: 'business-record-malformed',
  INACTIVE:  'business-not-active',
};

/**
 * ownerUid → canonical merchantId.
 *
 * The canonical merchant identity is the `businesses` DOCUMENT ID. `createBusiness` writes
 * that same value into a `merchantId` field, so a divergence between them means the record
 * has been edited by something that did not understand the contract — treated as malformed
 * rather than guessed at.
 *
 * `fdb` is optional: a caller already holding a Firestore handle (the POS commission rail, and
 * the tests that drive it against an emulator or an in-memory store) passes it, so the SAME
 * resolver answers for them instead of a second copy of this query.
 *
 * @returns {{ok: true, merchantId: string}|{ok: false, reason: string, count?: number}}
 */
async function resolveMerchantIdForOwner (ownerUid, fdb) {
  if (!ownerUid || typeof ownerUid !== 'string') {
    return { ok: false, reason: REASON.MALFORMED };
  }

  /* TWO, not one. Enough to detect ambiguity, still a cheap read. */
  const snap = await (fdb || db()).collection('businesses')
    .where('ownerId', '==', ownerUid)
    .limit(2)
    .get();

  if (snap.empty) return { ok: false, reason: REASON.UNLINKED };
  if (snap.size > 1) return { ok: false, reason: REASON.AMBIGUOUS, count: snap.size };

  const doc = snap.docs[0];
  const d = doc.data() || {};
  if (!doc.id || typeof doc.id !== 'string') return { ok: false, reason: REASON.MALFORMED };

  /* The doc id is canonical. If the stored field disagrees, refuse — silently preferring
     one over the other is how a tenant split starts. */
  if (d.merchantId && d.merchantId !== doc.id) {
    return { ok: false, reason: REASON.MALFORMED };
  }
  if (d.status && d.status !== 'active') {
    return { ok: false, reason: REASON.INACTIVE };
  }

  return { ok: true, merchantId: doc.id };
}

/**
 * True when `value` is this caller's own uid rather than a merchant identity. Used only to
 * recognise the LEGACY owner form of `sellerId` so it can be resolved forward — never to
 * grant anything.
 */
function looksLikeOwnerForm (value, authUid) {
  return !!value && !!authUid && value === authUid;
}

module.exports = { resolveMerchantIdForOwner, looksLikeOwnerForm, REASON };
